def calPoints(ops):
    record = []
    for op in ops:
        if op == "C":
            # Remove last score
            if record:
                record.pop()
        elif op == "D":
            # Double last score
            if record:
                record.append(2 * record[-1])
        elif op == "+":
            # Sum last two scores
            if len(record) >= 2:
                record.append(record[-1] + record[-2])
            elif len(record) == 1:
                record.append(record[-1])
        else:
            # Integer, add as new score
            record.append(int(op))
    return sum(record)
